import json,csv
root='artifacts/bloom_dataset_audit'; phase=root+'/phase3_semantic_validation'; rows=[json.loads(x) for x in open(root+'/extracted_dataset/source_extraction.jsonl',encoding='utf-8')]; by={r['example_id']:r for r in rows}
# per item: assessed, operation rationale, preservation, self containment, technical review, status, rationale, correction status, eligibility
A={
521:[('Remember','Recalls terms for intake, output, and net balance.','Same fluid-balance subject; categorical recall is a narrower subtask.','Yes','No defect.','PASS','','UNCHANGED','APPROVED'),('Understand','Interprets how measured intake and output are combined conceptually.','All four measures retained.','Yes','No defect.','PASS','','UNCHANGED','APPROVED'),('Analyze','Separates intake from output and relates each measure to the net.','All values retained.','Yes','Intake=1100mL; output=900mL; net=+200mL.','PASS','','UNCHANGED','APPROVED'),('Apply','Computes net by subtracting total output from intake; “verify” is a numerical procedure.','All conditions retained.','Yes','Reported +200mL is correct.','MAJOR','Arithmetic verification does not require criteria-based evaluation.','REVIEW_REQUIRED','NOT_APPROVED'),('Apply','Organizes supplied figures and performs the balance calculation; record format is routine.','All measures, interval, and calculated total retained.','Yes','Net +200mL.','MAJOR','A formatted record is not meaningful Create; it is routine application.','REVIEW_REQUIRED','NOT_APPROVED')],
522:[('Remember','Recalls test statistic and paired-test terms.','Same paired-test topic; details compressed to core method.','Yes','Formula conventions may vary but are standard.','PASS','','UNCHANGED','APPROVED'),('Understand','Explains dependence of observations because same five participants are measured twice.','Retains same students and before/after design.','Yes','Correct rationale for paired test.','PASS','','UNCHANGED','APPROVED'),('Analyze','Examines paired differences and their variability as inputs to the statistic.','All five pairs retained in source, though transformation refers to them without restating values; antecedent context is present in the original example but question should be standalone.','Partial','Values not restated.','MINOR','Question depends on the source’s score list; embed it for a standalone transformation.','REVIEW_REQUIRED','PENDING'),('Apply','Computes |t| and compares with stated critical value; this is a test procedure, not evaluation.','Significance level and critical value retained.','Yes','Expected paired differences 5,3,2,2,3; mean 3; sample SD≈1.225; t≈5.477, significant.','MAJOR','The operation is applying the test decision rule, not defensible evaluation beyond the procedure.','REVIEW_REQUIRED','NOT_APPROVED'),('Apply','Calculates paired differences, summary statistics, test statistic, and decision.','All method and conditions retained.','Yes','Based on supplied values, t≈5.477 >2.776.','MAJOR','A complete worked test solution executes a learned procedure; it is Apply.','REVIEW_REQUIRED','NOT_APPROVED')],
523:[('Remember','Recalls the meanings of machining parameters and outcomes.','Same CNC turning content.','Yes','No defect identified.','PASS','','UNCHANGED','APPROVED'),('Understand','Explains qualitative parameter effects on removal and finish.','All named parameters and outcomes retained.','Yes','Specific effects depend on material/tooling, but prompt asks general explanation.','PASS','','UNCHANGED','APPROVED'),('Apply','Chooses an adjustment for a stated machining goal; no speeds, material, or rule supplied.','Same topic, but adds an unspecified operational goal and implies one parameter selection.','No','Multiple parameters affect MRR; cannot identify uniquely without process conditions or rule.','REVIEW','Underspecified; safe answer cannot be uniquely inferred.','REVIEW_REQUIRED','PENDING'),('Evaluate','Judges a strategy against two explicit outcomes (higher MRR, acceptable finish), but acceptable finish has no criterion.','Same parameters and objectives.','Partial','No process/material/finish criterion given.','REVIEW','Evaluation standard and process conditions are absent.','REVIEW_REQUIRED','PENDING'),('Create','Constructs a framework linking parameters to both outcomes.','Same scope and variables.','Yes','Conceptual framework is feasible; no numeric assumptions.','PASS','','UNCHANGED','APPROVED')],
524:[('Remember','Recognizes the three named budget considerations.','Retains all three core concepts.','Yes','No defect.','PASS','','UNCHANGED','APPROVED'),('Understand','Explains revenue/fiscal limits’ effect on expenditure resources.','Retains the key relationship; expenditure priorities remain contextual.','Yes','No defect.','PASS','','UNCHANGED','APPROVED'),('Apply','Classifies expenditure proposals by priority, but no proposals or priority rule are supplied.','Retains budgeting concepts but adds absent proposals and criteria.','No','Cannot classify unspecified proposed expenditures.','REVIEW','Requires a list of expenditures and a prioritization rule.','REVIEW_REQUIRED','PENDING'),('Evaluate','Makes judgment on feasibility against stated comparison of outlays exceeding available revenues.','Retains budget allocation and fiscal constraint concepts.','Yes','General judgment criteria explicit: expenditures exceed resources.','PASS','','UNCHANGED','APPROVED'),('Create','Builds a framework connecting the three factors.','Preserves all named concepts and objective.','Yes','No technical assumptions.','PASS','','UNCHANGED','APPROVED')],
525:[('Remember','Recalls equation and what the intercepts represent.','Same enzyme-kinetics content.','Yes','Lineweaver–Burk: y-intercept=1/Vmax; x-intercept=−1/Km.','PASS','','UNCHANGED','APPROVED'),('Understand','Interprets the intercepts as reciprocals.','Both supplied intercepts and meanings retained.','Yes','Units consistent with reciprocal quantities.','PASS','','UNCHANGED','APPROVED'),('Analyze','Examines sign/magnitude relationships; however computing parameters is mainly formula application.','Both intercepts retained.','Yes','Vmax=50 µmol/min; Km=2 mmol/L.','MAJOR','Determining parameter values from intercepts is routine application; no relationship analysis beyond inversion is needed.','REVIEW_REQUIRED','NOT_APPROVED'),('Apply','Checks reported values by inverting intercepts; this is numerical procedure.','Values and units retained.','Yes','Reported values are correct.','MAJOR','Numerical verification is Apply rather than Evaluate.','REVIEW_REQUIRED','NOT_APPROVED'),('Apply','Derives parameters by reciprocal calculation; a derivation template is execution of method.','Both intercepts retained.','Yes','Expected Vmax=50 µmol/min; Km=2 mmol/L.','MAJOR','Worked parameter-estimation derivation is Apply, not new construction.','REVIEW_REQUIRED','NOT_APPROVED')]}
fields=['example_id','discipline_course_topic','source_question','source_bloom_declared','target_bloom_declared','transformed_question','target_bloom_assessed','actual_cognitive_demand_reasoning','content_preservation','self_containment','technical_correctness','status','status_reason','audit_state','correction_status','training_eligibility']
out=[]
for eid,aa in A.items():
 r=by[eid]
 for t,a in zip(r['transformations'],aa):
  lev,reason,pres,sc,tech,st,why,corr,elig=a
  out.append(dict(example_id=eid,discipline_course_topic=r['discipline_course_topic'],source_question=r['original_question'],source_bloom_declared=r['original_bloom'],target_bloom_declared=t['target_bloom'],transformed_question=t['transformed_question'],target_bloom_assessed=lev,actual_cognitive_demand_reasoning=reason,content_preservation=pres,self_containment=sc,technical_correctness=tech,status=st,status_reason=why,audit_state='Independent semantic review batch 521-525',correction_status=corr,training_eligibility=elig))
with open(phase+'/transformation_batch_examples_521_525.csv','w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(out)
